<?php declare(strict_types=1); /** @var Closure(mixed):string $escape */ $statusNames=['open'=>'Aberto','in_progress'=>'Em andamento','waiting'=>'Aguardando','resolved'=>'Resolvido','closed'=>'Fechado'];$priorityNames=['low'=>'Baixa','normal'=>'Normal','high'=>'Alta','urgent'=>'Urgente']; ?>
<header class="section-heading"><div><span class="status">Demandas internas</span><h1>Tickets</h1><p class="meta">Acompanhe chamados abertos e recebidos entre os setores.</p></div><?php if($canCreate):?><a class="button-primary" href="<?= $escape($basePath) ?>/tickets/create"><i class="fa-solid fa-plus"></i> Novo ticket</a><?php endif;?></header>
<?php if($message):?><p class="alert alert-success"><?= $escape($message) ?></p><?php endif;?>
<div class="dashboard-grid mb-4"><article class="metric-card"><span>Tickets do seu setor</span><strong><?= (int)$summary['open'] ?></strong></article><article class="metric-card"><span>Não lidos</span><strong><?= (int)$summary['unread'] ?></strong></article><article class="metric-card"><span>Atrasados</span><strong class="finance-open-value"><?= (int)$summary['overdue'] ?></strong></article></div>
<form class="ticket-filters" method="get"><input name="q" value="<?= $escape($search) ?>" placeholder="Buscar ticket, aluno ou setor"><select name="scope"><option value="">Todos os visíveis</option><option value="mine"<?= $scope==='mine'?' selected':'' ?>>Do meu setor</option><option value="created"<?= $scope==='created'?' selected':'' ?>>Abertos por mim</option><option value="overdue"<?= $scope==='overdue'?' selected':'' ?>>Atrasados</option></select><select name="status"><option value="">Todos os status</option><?php foreach($statusNames as$value=>$label):?><option value="<?= $value ?>"<?= $status===$value?' selected':'' ?>><?= $label ?></option><?php endforeach;?></select><select name="priority"><option value="">Todas as prioridades</option><?php foreach($priorityNames as$value=>$label):?><option value="<?= $value ?>"<?= $priority===$value?' selected':'' ?>><?= $label ?></option><?php endforeach;?></select><button class="button-primary" type="submit">Filtrar</button><a class="button-secondary" href="<?= $escape($basePath) ?>/tickets">Limpar</a></form>
<div class="table-responsive ticket-table"><table><thead><tr><th>Ticket</th><th>Aluno/Contato</th><th>Unidade</th><th>Prioridade</th><th>Status</th><th>Solicitante</th><th>Setor</th><th>Prazo</th></tr></thead><tbody><?php if($tickets===[]):?><tr><td colspan="8"><div class="finance-empty"><i class="fa-solid fa-ticket"></i><strong>Nenhum ticket encontrado</strong></div></td></tr><?php endif;?><?php foreach($tickets as$ticket):?><tr class="<?= (int)$ticket['unread']===1?'ticket-unread':'' ?>"><td><a class="ticket-subject" href="<?= $escape($basePath) ?>/tickets/<?= (int)$ticket['id'] ?>"><?php if((int)$ticket['unread']===1):?><span class="ticket-unread-dot"></span><?php endif;?><span><strong>#<?= (int)$ticket['id'] ?> · <?= $escape($ticket['subject']) ?></strong><small>Atualizado em <?= $escape(date('d/m/Y H:i',strtotime($ticket['updated_at']))) ?></small></span></a></td><td><?= $escape($ticket['contact_name']) ?></td><td><?= $escape($ticket['unit_name']) ?></td><td><span class="ticket-priority priority-<?= $escape($ticket['priority']) ?>"><?= $escape($priorityNames[$ticket['priority']]??$ticket['priority']) ?></span></td><td><span class="connection-badge"><?= $escape($statusNames[$ticket['status']]??$ticket['status']) ?></span></td><td><?= $escape($ticket['requester_name']) ?></td><td><?= $escape($ticket['department_name']) ?></td><td><?= $ticket['due_at']?$escape(date('d/m/Y H:i',strtotime($ticket['due_at']))):'—' ?></td></tr><?php endforeach;?></tbody></table></div>
